def resoudre(zone, nom):
    while nom in zone:
        genre, valeur = zone[nom]
        if genre == "A":
            return valeur
        nom = valeur
    return None

def niveaux(nom):
    parties = nom.split(".")
    return [".".join(parties[i:]) for i in range(len(parties) - 1, -1, -1)]

