exercises.solution:
def depuis_cache(cache, nom, maintenant):
    if nom not in cache:
        return None
    ip, expiration = cache[nom]
    if maintenant < expiration:
        return ip
    return None

def resoudre_prudent(zone, nom, limite):
    sauts = 0
    while True:
        if nom not in zone:
            raise ValueError("nom inconnu")
        genre, valeur = zone[nom]
        if genre == "A":
            return valeur
        sauts += 1
        if sauts > limite:
            raise ValueError("trop de redirections")
        nom = valeur
